import type { ReactNode } from "react";

type IconShape = { viewBox: string; body: ReactNode };

// Placeholder icons until we got the Figma ones
function drawn(body: ReactNode): IconShape {
  return {
    viewBox: "0 0 24 24",
    body: (
      <g
        fill="none"
        stroke="currentColor"
        strokeWidth={1.5}
        strokeLinecap="round"
        strokeLinejoin="round"
      >
        {body}
      </g>
    ),
  };
}

// Figma icons, black swapped to currentColor so CSS can colour them
function filled(viewBox: string, d: string): IconShape {
  return {
    viewBox,
    body: <path fillRule="evenodd" clipRule="evenodd" fill="currentColor" d={d} />,
  };
}

// Grey fill with a dark outline, the toolbar style in Figma
function shaded(viewBox: string, ...paths: string[]): IconShape {
  return {
    viewBox,
    body: (
      <g fill="currentColor" fillOpacity={0.5} stroke="currentColor">
        {paths.map((d) => (
          <path key={d} d={d} />
        ))}
      </g>
    ),
  };
}

