export type IconName = keyof typeof icons;

export function Icon({ name }: { name: IconName }) {
  const { viewBox, body } = icons[name];
  return (
    <svg className="icon" viewBox={viewBox} aria-hidden="true">
      {body}
    </svg>
  );
}
